// Separate complete art cells, never rectangular cuts through assembled stacks.
// Sheet source bounds are generated by scripts/register-home-layers.py.
export const HOME_LAYER_PLACEMENTS = {
  lighthouse: { id:'mugs', base:[329,360,240,1430], top:[298,143,255,240], cls:'hs-cup-top', pivot:'51% 20.7%' },
  wheels: { id:'cones', base:[302,302,239,1444], top:[318,43,243,294], cls:'hs-cone-top', pivot:'50% 18.2%' },
  'toy-box': { id:'blocks', base:[174,340,525,1418], top:[257,149,335,200], cls:'hs-block-roof', pivot:'50% 18.9%' },
  snacks: { id:'cherry', base:[207,252,425,1552], top:[330,48,170,240], cls:'hs-cherry', pivot:'49% 15.5%' },
  giraffe: { id:'ducks', base:[275,258,263,1459], top:[270,38,260,250], cls:'hs-duck-top', pivot:'47% 15.6%' },
  penguin: { id:'ice', base:[298,364,262,1338], top:[294,106,268,278], cls:'hs-ice-top', pivot:'53% 20.4%' },
  corgi: { id:'bowls', base:[353,360,391,1170], top:[353,135,390,260], cls:'hs-bowl-top', pivot:'53% 25%' },
  dragon: { id:'coins', base:[285,335,290,1474], top:[300,82,300,300], cls:'hs-coin-top', pivot:'52% 20.8%' },
};

export function artCell(image, crop, placement, spec, cls, byHeight=false) {
  const [x,y,w,h]=placement, [cx,cy,cw,ch]=crop;
  const k=byHeight?h/ch:Math.min(w/cw,h/ch), width=cw*k,height=ch*k;
  const cell=document.createElement('div');cell.className='hs-art-cell '+cls;
  cell.style.cssText=`left:${(x+(w-width)/2)/spec.sw*100}%;top:${(y+h-height)/spec.sh*100}%;width:${width/spec.sw*100}%;height:${height/spec.sh*100}%`;
  const sprite=image.cloneNode();sprite.className='hs-cell-image';sprite.alt='';
  sprite.style.cssText=`left:${-cx/cw*100}%;top:${-cy/ch*100}%;width:${image.naturalWidth/cw*100}%;height:${image.naturalHeight/ch*100}%`;
  cell.appendChild(sprite);return cell;
}

export function assembleHomeProp(scene,{hop,img,spec,extras},sheets) {
  const p=HOME_LAYER_PLACEMENTS[scene];if(!p)return null;
  const sheet=sheets[p.id],image=extras.get(sheet.file);
  img.hidden=true;img.style.display='none';
  const base=artCell(image,sheet.base,p.base,spec,'hs-complete-stack',true);hop.appendChild(base);
  const top=document.createElement('div');top.className='hs-detail '+p.cls;top.style.transformOrigin=p.pivot;
  top.appendChild(artCell(image,sheet.top,p.top,spec,'hs-isolated-top'));hop.appendChild(top);
  if(scene==='corgi'){
    const bowl=top.firstChild,well=document.createElement('div');well.className='hs-kibble-well';
    for(let i=0;i<23;i++){
      const piece=extras.get('refined/kibble.webp').cloneNode();piece.alt='';piece.className='hs-kibble-piece';
      const row=Math.floor(i/6),col=i%6;
      piece.style.cssText=`--ki:${i};--dx:${i%2?1:-1};--turn:${(i%5-2)*8}deg;left:${17+col*11+(row%2)*4}%;top:${9+row*6.5}%;width:${11+i%3}%;--kd:${i%7*.025}s`;
      well.appendChild(piece);
    }
    bowl.appendChild(well);
    const lip=artCell(image,sheet.top,p.top,spec,'hs-bowl-front');top.appendChild(lip);
    return {top};
  }
  if(scene==='giraffe'){
    const eye=document.createElement('i');eye.className='hs-duck-eye';top.firstChild.appendChild(eye);
  }
  if(scene==='dragon'){
    const texture=top.firstChild;texture.className+=' hs-coin-face hs-coin-front';
    // A cylinder has real thickness: two circular textured faces and an edge
    // made of small quads. It never collapses into a paper-thin angled PNG.
    const rotor=document.createElement('div');rotor.className='hs-coin-cylinder';
    top.replaceChildren(rotor);texture.style.cssText='';rotor.appendChild(texture);
    const back=texture.cloneNode(true);back.classList.replace('hs-coin-front','hs-coin-back');rotor.appendChild(back);
    for(let i=0;i<64;i++){const edge=document.createElement('i');edge.className='hs-coin-edge';edge.style.setProperty('--edge-angle',`${i*360/64}deg`);rotor.appendChild(edge);}
    const [x,y,w,h]=p.top;top.style.left=x/spec.sw*100+'%';top.style.top=y/spec.sh*100+'%';top.style.width=w/spec.sw*100+'%';top.style.height=h/spec.sh*100+'%';top.style.transformOrigin='50% 100%';
  }
  return {top};
}
